sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float mode;
uniform float contrast;
uniform float shift;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 b = float4(blurred.eval(coord));
    float na = mode < 0.5 ? b.a : (mode < 1.5 ? min(c.a, b.a) : max(c.a, b.a));
    na = saturate((na - 0.5 + shift * 0.5) * contrast + 0.5);
    na = mix(c.a, na, amount);
    float3 col = mix(unp(b), unp(c), saturate(c.a * 4.0));
    return fin(c, float4(col * na, na), opacity);
}
